// Production-path regressions for the automatic WAV take-end policy.
// Every output is generated by exportTakeAsWavFile() or
// renderTakeWithOfflinePlugin(); no direct Voice harness is used.
namespace {

constexpr auto kTargetRate = 48000.0;
constexpr int kBlockSize = 512;
constexpr int kShortTake = 12000;
constexpr int kReferenceExtraSamples = 48000;

struct TestEvent {
    std::int64_t sample = 0;
    int channel = 1;
    int number = 60;
    int value = 0;
    enum class Kind { noteOn, noteOff, controller } kind = Kind::noteOn;
};

struct Scenario {
    juce::String name;
    double sourceRate = kTargetRate;
    std::int64_t length = kShortTake;
    std::vector<TestEvent> events;
    bool plugin = false;
    bool dualLayer = false;
    bool sine = false;
};

struct CapturedMidi {
    std::int64_t globalSample = 0;
    int blockOffset = 0;
    juce::String description;
    bool allSoundOff = false;
    bool allNotesOff = false;
};

class ReleaseTailTestPlugin final : public juce::AudioPluginInstance {
public:
    ReleaseTailTestPlugin()
        : AudioPluginInstance(BusesProperties()
                                  .withInput("Input", juce::AudioChannelSet::stereo(), true)
                                  .withOutput("Output", juce::AudioChannelSet::stereo(), true)) {
    }

    const juce::String getName() const override {
        return "ReleaseTailTestPlugin";
    }
    void prepareToPlay(double, int) override {
        activeNote = -1;
        releaseRemaining = 0;
        hardStopped = false;
        globalSample = 0;
        events.clear();
    }
    void releaseResources() override {
    }
    void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer& midiMessages) override {
        auto event = midiMessages.begin();
        const auto end = midiMessages.end();
        for (int sample = 0; sample < buffer.getNumSamples(); ++sample) {
            while (event != end && (*event).samplePosition <= sample) {
                consume((*event).getMessage(), (*event).samplePosition);
                ++event;
            }
            auto value = 0.0f;
            if (activeNote >= 0) {
                value = 0.2f;
            } else if (releaseRemaining > 0) {
                value = 0.2f * static_cast<float>(releaseRemaining) / 4800.0f;
            }
            if (activeNote < 0 && releaseRemaining > 0) {
                --releaseRemaining;
            }
            for (int channel = 0; channel < buffer.getNumChannels(); ++channel) {
                buffer.setSample(channel, sample, value);
            }
        }
        while (event != end) {
            consume((*event).getMessage(), (*event).samplePosition);
            ++event;
        }
        globalSample += buffer.getNumSamples();
    }
    double getTailLengthSeconds() const override {
        return 1.0;
    }
    bool acceptsMidi() const override {
        return true;
    }
    bool producesMidi() const override {
        return false;
    }
    juce::AudioProcessorEditor* createEditor() override {
        return nullptr;
    }
    bool hasEditor() const override {
        return false;
    }
    int getNumPrograms() override {
        return 1;
    }
    int getCurrentProgram() override {
        return 0;
    }
    void setCurrentProgram(int) override {
    }
    const juce::String getProgramName(int) override {
        return {};
    }
    void changeProgramName(int, const juce::String&) override {
    }
    void getStateInformation(juce::MemoryBlock&) override {
    }
    void setStateInformation(const void*, int) override {
    }
    void fillInPluginDescription(juce::PluginDescription& description) const override {
        description.name = getName();
        description.pluginFormatName = "VST3";
        description.numInputChannels = 2;
        description.numOutputChannels = 2;
    }

    std::vector<CapturedMidi> events;

private:
    void consume(const juce::MidiMessage& message, int blockOffset) {
        CapturedMidi event;
        event.globalSample = globalSample + blockOffset;
        event.blockOffset = blockOffset;
        event.description = message.getDescription();
        event.allSoundOff = message.isAllSoundOff();
        event.allNotesOff = message.isAllNotesOff();
        events.push_back(event);
        if (message.isNoteOn()) {
            activeNote = message.getNoteNumber();
            releaseRemaining = 0;
            hardStopped = false;
        } else if (message.isNoteOff()) {
            activeNote = -1;
            releaseRemaining = 4800;
            hardStopped = false;
        } else if (message.isAllSoundOff()) {
            activeNote = -1;
            releaseRemaining = 0;
            hardStopped = true;
        } else if (message.isAllNotesOff() && !hardStopped) {
            activeNote = -1;
            releaseRemaining = 4800;
        }
    }

    int activeNote = -1;
    int releaseRemaining = 0;
    bool hardStopped = false;
    std::int64_t globalSample = 0;
};

devpiano::recording::PerformanceEvent makeEvent(const TestEvent& spec) {
    devpiano::recording::PerformanceEvent event;
    event.timestampSamples = spec.sample;
    event.type = devpiano::recording::PerformanceEventType::midi;
    event.source = devpiano::recording::RecordingEventSource::playback;
    if (spec.kind == TestEvent::Kind::noteOn) {
        event.message = juce::MidiMessage::noteOn(spec.channel, spec.number, static_cast<float>(spec.value) / 127.0f);
    } else if (spec.kind == TestEvent::Kind::noteOff) {
        event.message = juce::MidiMessage::noteOff(spec.channel, spec.number);
    } else {
        event.message = juce::MidiMessage::controllerEvent(spec.channel, spec.number, spec.value);
    }
    return event;
}

devpiano::recording::RecordingTake makeTake(const Scenario& scenario) {
    devpiano::recording::RecordingTake take;
    take.sampleRate = scenario.sourceRate;
    take.lengthSamples = scenario.length;
    for (const auto& event : scenario.events) {
        take.events.push_back(makeEvent(event));
    }
    return take;
}

devpiano::exporting::WavExportOptions makeOptions(const Scenario& scenario) {
    devpiano::exporting::WavExportOptions options;
    options.tailSeconds = 2.0;
    options.sampleRate = kTargetRate;
    options.numChannels = 2;
    options.blockSize = kBlockSize;
    options.bitsPerSample = 24;
    options.masterGain = 1.0f;
    options.adsr = { 0.01f, 0.2f, 0.8f, 0.3f };
    options.builtinTone = scenario.sine ? SettingsModel::BuiltinTone::sine : SettingsModel::BuiltinTone::piano;
    options.reverbWet = 0.0f;
    options.pedalNoiseLevel = 0.0f;
    if (scenario.dualLayer) {
        options.layers.enabled = true;
        options.layers.pianoEnabled = true;
        options.layers.pluginEnabled = true;
        options.layers.pianoGain = 0.5f;
        options.layers.pluginGain = 0.5f;
    }
    return options;
}

void appendClosureEvent(devpiano::recording::RecordingTake& take, std::int64_t sample,
                        const juce::MidiMessage& message) {
    take.events.push_back({ sample, devpiano::recording::PerformanceEventType::midi, 0,
                            devpiano::recording::RecordingEventSource::playback, message });
}

std::unique_ptr<juce::AudioFormatReader> makeReader(const juce::File& file) {
    juce::AudioFormatManager formats;
    formats.registerBasicFormats();
    return std::unique_ptr<juce::AudioFormatReader>(formats.createReaderFor(file));
}

bool readAudio(const juce::File& file, juce::AudioBuffer<float>& buffer, double& sampleRate) {
    auto reader = makeReader(file);
    if (reader == nullptr) {
        return false;
    }
    sampleRate = reader->sampleRate;
    buffer.setSize(static_cast<int>(reader->numChannels), static_cast<int>(reader->lengthInSamples));
    return reader->read(buffer.getArrayOfWritePointers(), buffer.getNumChannels(), 0, buffer.getNumSamples());
}

float maximumDifference(const juce::AudioBuffer<float>& left, const juce::AudioBuffer<float>& right, int frames) {
    auto difference = 0.0f;
    for (int channel = 0; channel < left.getNumChannels(); ++channel) {
        for (int sample = 0; sample < frames; ++sample) {
            difference
                = std::max(difference, std::abs(left.getSample(channel, sample) - right.getSample(channel, sample)));
        }
    }
    return difference;
}

int lastNonzeroFrame(const juce::AudioBuffer<float>& buffer) {
    auto last = -1;
    for (int channel = 0; channel < buffer.getNumChannels(); ++channel) {
        for (int sample = 0; sample < buffer.getNumSamples(); ++sample) {
            if (buffer.getSample(channel, sample) != 0.0f) {
                last = sample;
            }
        }
    }
    return last;
}

int countAllSoundOff(const std::vector<CapturedMidi>& events) {
    return static_cast<int>(
        std::count_if(events.begin(), events.end(), [](const auto& event) { return event.allSoundOff; }));
}

int countAllNotesOff(const std::vector<CapturedMidi>& events) {
    return static_cast<int>(
        std::count_if(events.begin(), events.end(), [](const auto& event) { return event.allNotesOff; }));
}

class ExportTailEndTest final : public juce::UnitTest {
public:
    ExportTailEndTest()
        : juce::UnitTest("ExportTailEnd", "DevPiano/Recording") {
    }

    void runTest() override {
        testReleaseCrossesBoundary();
        testScaledNoteOffAtTakeEnd();
        testHeldNoteAtBlockBoundary();
        testNormalRecordingClose();
        testSustainPedalHeldNote();
        testSostenutoHeldNote();
        testSineReleaseAtBoundary();
        testZeroVelocityNoteOn();
        testExplicitCc120HardStop();
        testPluginReleaseAndMessageTable();
        testDualLayerReleaseAndMessageTable();
    }

private:
    devpiano::test::ScopedTempDir tempDir { "export-tail-end" };

    void runScenario(const Scenario& scenario, bool referenceNeedsClosureNoteOff, bool expectNoAutomaticPanic) {
        beginTest(scenario.name);
        auto take = makeTake(scenario);
        if (scenario.name == "normal-recording-close") {
            devpiano::recording::RecordingEngine engine;
            engine.reserveEvents(8);
            engine.startRecording(kTargetRate);
            engine.recordEvent(juce::MidiMessage::noteOn(1, 60, 0.75f),
                               devpiano::recording::RecordingEventSource::computerKeyboard, 0);
            engine.advanceRecordingPosition(kShortTake);
            take = engine.stopRecording();
        }

        const auto shortTimeline = devpiano::recording::prepareRenderTimeline(take, kTargetRate, 2.0);
        expect(shortTimeline.has_value(), "short timeline must be valid");
        if (!shortTimeline.has_value()) {
            return;
        }

        const auto closureSource = static_cast<std::int64_t>(
            std::llround(static_cast<double>(shortTimeline->takeLengthSamples) * scenario.sourceRate / kTargetRate));
        auto reference = take;
        const auto targetReferenceLength = shortTimeline->totalSamples + kReferenceExtraSamples;
        const auto sourceReferenceLength
            = static_cast<std::int64_t>(
                  std::ceil(static_cast<double>(targetReferenceLength) * scenario.sourceRate / kTargetRate))
            + 1;
        reference.lengthSamples = std::max(take.lengthSamples, sourceReferenceLength);
        if (referenceNeedsClosureNoteOff) {
            appendClosureEvent(reference, closureSource, juce::MidiMessage::noteOff(1, 60, 0.0f));
        }
        for (int channel = 1; channel <= 16; ++channel) {
            appendClosureEvent(reference, closureSource, juce::MidiMessage::controllerEvent(channel, 64, 0));
            appendClosureEvent(reference, closureSource, juce::MidiMessage::controllerEvent(channel, 66, 0));
            appendClosureEvent(reference, closureSource, juce::MidiMessage::controllerEvent(channel, 67, 0));
        }

        const auto referenceTimeline = devpiano::recording::prepareRenderTimeline(reference, kTargetRate, 2.0);
        expect(referenceTimeline.has_value(), "reference timeline must be valid");
        if (!referenceTimeline.has_value()) {
            return;
        }
        expectGreaterThan(referenceTimeline->takeLengthSamples, shortTimeline->totalSamples,
                          "reference automatic end must be outside the compared interval");

        const auto options = makeOptions(scenario);
        const auto shortFile = tempDir.getChildFile(scenario.name + "-short.wav");
        const auto referenceFile = tempDir.getChildFile(scenario.name + "-reference.wav");
        ReleaseTailTestPlugin shortPlugin;
        ReleaseTailTestPlugin referencePlugin;
        bool shortRendered = false;
        bool referenceRendered = false;
        if (scenario.plugin) {
            shortRendered = devpiano::exporting::renderTakeWithOfflinePlugin(take, shortFile, options, shortPlugin);
            referenceRendered
                = devpiano::exporting::renderTakeWithOfflinePlugin(reference, referenceFile, options, referencePlugin);
        } else {
            shortRendered = devpiano::exporting::exportTakeAsWavFile(take, shortFile, options);
            referenceRendered = devpiano::exporting::exportTakeAsWavFile(reference, referenceFile, options);
        }
        expect(shortRendered, "short render must succeed");
        expect(referenceRendered, "reference render must succeed");
        if (!shortRendered || !referenceRendered) {
            return;
        }

        juce::AudioBuffer<float> shortAudio;
        juce::AudioBuffer<float> referenceAudio;
        double shortRate = 0.0;
        double referenceRate = 0.0;
        expect(readAudio(shortFile, shortAudio, shortRate), "short WAV must be readable");
        expect(readAudio(referenceFile, referenceAudio, referenceRate), "reference WAV must be readable");
        expectWithinAbsoluteError(shortRate, kTargetRate, 0.001);
        expectWithinAbsoluteError(referenceRate, kTargetRate, 0.001);
        expectEquals(static_cast<std::int64_t>(shortAudio.getNumSamples()), shortTimeline->totalSamples,
                     "short file length must equal timeline totalSamples");
        expectGreaterThan(referenceAudio.getNumSamples(), shortAudio.getNumSamples());

        const auto comparedFrames = shortAudio.getNumSamples();
        expectLessThan(maximumDifference(shortAudio, referenceAudio, comparedFrames), 1.0e-6f,
                       "normal release must match the explicit release reference sample-for-sample");

        if (scenario.plugin && expectNoAutomaticPanic) {
            expectEquals(countAllSoundOff(shortPlugin.events), 0, "normal take end must not send All Sound Off");
            expectEquals(countAllNotesOff(shortPlugin.events), 0, "normal take end must not send All Notes Off");
        }

        if (scenario.name == "explicit-cc120-hard-stop") {
            expectEquals(countAllSoundOff(shortPlugin.events), 1, "explicit CC120 must remain the only All Sound Off");
            expectEquals(countAllNotesOff(shortPlugin.events), 0,
                         "explicit CC120 must not gain an automatic All Notes Off");
            const auto last = lastNonzeroFrame(shortAudio);
            expectLessThan(last, 6000, "explicit CC120 hard stop must silence the plugin after 6000");
        }
    }

    void testReleaseCrossesBoundary() {
        runScenario({ "release-crosses-boundary",
                      kTargetRate,
                      kShortTake,
                      { { 0, 1, 60, 96, TestEvent::Kind::noteOn }, { 10000, 1, 60, 0, TestEvent::Kind::noteOff } } },
                    false, false);
    }

    void testScaledNoteOffAtTakeEnd() {
        runScenario({ "scaled-noteoff-at-end",
                      44100.0,
                      11025,
                      { { 0, 1, 60, 96, TestEvent::Kind::noteOn }, { 11025, 1, 60, 0, TestEvent::Kind::noteOff } } },
                    false, false);
    }

    void testHeldNoteAtBlockBoundary() {
        runScenario({ "held-note-block-boundary", kTargetRate, 12288, { { 0, 1, 60, 96, TestEvent::Kind::noteOn } } },
                    true, false);
    }

    void testNormalRecordingClose() {
        runScenario({ "normal-recording-close", kTargetRate, kShortTake, {}, false, false, false }, false, false);
    }

    void testSustainPedalHeldNote() {
        runScenario({ "sustain-pedal-held",
                      kTargetRate,
                      kShortTake,
                      { { 0, 1, 64, 127, TestEvent::Kind::controller },
                        { 0, 1, 60, 96, TestEvent::Kind::noteOn },
                        { 8000, 1, 60, 0, TestEvent::Kind::noteOff } } },
                    false, false);
    }

    void testSostenutoHeldNote() {
        runScenario({ "sostenuto-held",
                      kTargetRate,
                      kShortTake,
                      { { 0, 1, 66, 127, TestEvent::Kind::controller },
                        { 0, 1, 60, 96, TestEvent::Kind::noteOn },
                        { 8000, 1, 60, 0, TestEvent::Kind::noteOff } } },
                    false, false);
    }

    void testSineReleaseAtBoundary() {
        runScenario({ "sine-release",
                      kTargetRate,
                      kShortTake,
                      { { 0, 1, 60, 96, TestEvent::Kind::noteOn }, { 10000, 1, 60, 0, TestEvent::Kind::noteOff } },
                      false,
                      false,
                      true },
                    false, false);
    }

    void testZeroVelocityNoteOn() {
        runScenario({ "zero-velocity-noteoff",
                      kTargetRate,
                      kShortTake,
                      { { 0, 1, 60, 96, TestEvent::Kind::noteOn }, { 8000, 1, 60, 0, TestEvent::Kind::noteOn } } },
                    false, false);
    }

    void testExplicitCc120HardStop() {
        runScenario({ "explicit-cc120-hard-stop",
                      kTargetRate,
                      kShortTake,
                      { { 0, 1, 60, 96, TestEvent::Kind::noteOn },
                        { 6000, 1, 120, 0, TestEvent::Kind::controller },
                        { 10000, 1, 60, 0, TestEvent::Kind::noteOff } },
                      true,
                      false,
                      false },
                    false, false);
    }

    void testPluginReleaseAndMessageTable() {
        runScenario({ "plugin-release",
                      kTargetRate,
                      kShortTake,
                      { { 0, 1, 60, 96, TestEvent::Kind::noteOn }, { 10000, 1, 60, 0, TestEvent::Kind::noteOff } },
                      true,
                      false,
                      false },
                    false, true);
    }

    void testDualLayerReleaseAndMessageTable() {
        runScenario({ "dual-layer-release",
                      kTargetRate,
                      kShortTake,
                      { { 0, 1, 60, 96, TestEvent::Kind::noteOn }, { 10000, 1, 60, 0, TestEvent::Kind::noteOff } },
                      true,
                      true,
                      false },
                    false, true);
    }
};

ExportTailEndTest exportTailEndTest;

} // namespace
